VCE.stimuli('psychology', {
  'u3-noor': { html: `<p>Noor, 17, is learning to drive a manual car. At first she had to think about every step of changing gears, and the car often jerked. After weeks of practice, changing gears is smooth and she barely thinks about it. Last week the car stalled on a steep hill with traffic behind her. Her heart pounded, her hands shook and she breathed quickly, but she restarted the car and drove on.</p>` },
  'u3-dev': { html: `<p>In the weeks before his exams, Dev often has an upset stomach and diarrhoea. He tells his friend, "If I don't get a high ATAR my parents will be so disappointed, and there's no one I can ask for help with Specialist Maths."</p>` },
  'u3-nurse': { html: `<p>Ines is a new graduate nurse. On her first ward, the pager beep was usually followed by an emergency, which made her heart race and her stomach tighten. Now her heart races whenever she hears any beep similar to the pager, even at the supermarket.</p><p>Ines also noticed that a senior nurse, Raj, always cleans his hands carefully before and after every patient, and the nurse unit manager praises him at every team meeting. Ines now cleans her hands in exactly the same way.</p>` },
  'u4-cycles': {
    html: `<p>A sleep laboratory recorded a healthy 35-year-old over one night. The table shows the minutes spent in NREM Stage 3 and in REM sleep during each 90-minute sleep cycle.</p>
<table><tr><th>Cycle</th><th>1</th><th>2</th><th>3</th><th>4</th><th>5</th></tr><tr><td>NREM Stage 3 (min)</td><td>40</td><td>28</td><td>12</td><td>4</td><td>0</td></tr><tr><td>REM (min)</td><td>8</td><td>16</td><td>24</td><td>32</td><td>38</td></tr></table>`,
  },
  'u4-hamid': { html: `<p>Hamid is a fly-in fly-out mine worker. For two weeks at a time he works 12-hour night shifts (6 pm – 6 am) and tries to sleep in a hot, bright donga (portable cabin) during the day. He eats a large meal and drinks two cans of cola as soon as his shift ends. He says he feels "jet-lagged" for the whole two weeks.</p>` },
  'u4-lily': { html: `<p>Lily, 9, has a specific phobia of thunderstorms. During a severe storm two years ago, a tree fell on the family's carport with a loud crash while Lily was watching from the window. Now she checks the weather forecast many times a day, refuses to go to school if storms are forecast, and hides in the bathroom when it rains heavily. Her parents let her stay home whenever a storm is forecast "so she doesn't get upset".</p>` },
});

const U3 = (n) => `u3-a${String(n).padStart(2, '0')}`;
const U4 = (n) => `u4-a${String(n).padStart(2, '0')}`;

